# Independent simulation of the Ring class, program trace and the modified full test
class Ring:
    def __init__(self, cap, size_test=False):
        self.a = [None]*cap; self.cap = cap; self.head = 0; self.tail = 0; self.size_test = size_test
    def size(self): return (self.tail - self.head) % self.cap
    def enq(self, x):
        full = (self.size() == self.cap) if self.size_test else ((self.tail + 1) % self.cap == self.head)
        if full: return False
        self.a[self.tail] = x; self.tail = (self.tail + 1) % self.cap; return True
    def deq(self):
        if self.head == self.tail: return None
        x = self.a[self.head]; self.head = (self.head + 1) % self.cap; return x
q = Ring(5); res = {}
